// One-time generator: reads the downloaded Leaflet JS+CSS and writes
// src/leafletAssets.ts exporting them as strings, so the map WebView can inline
// Leaflet (no network fetch on open). Run: node scripts/bundleLeaflet.js
const fs = require("fs");
const path = require("path");

const js = fs.readFileSync(path.join(__dirname, "..", "assets", "leaflet", "leaflet.js"), "utf8");
const css = fs.readFileSync(path.join(__dirname, "..", "assets", "leaflet", "leaflet.css"), "utf8");

// Use a tagged template via JSON.stringify to safely escape everything.
const out =
  "// AUTO-GENERATED by scripts/bundleLeaflet.js — do not edit by hand.\n" +
  "// Inlined Leaflet 1.9.4 so the map loads with no network fetch.\n" +
  "export const LEAFLET_JS = " + JSON.stringify(js) + ";\n" +
  "export const LEAFLET_CSS = " + JSON.stringify(css) + ";\n";

const dest = path.join(__dirname, "..", "src", "leafletAssets.ts");
fs.writeFileSync(dest, out, "utf8");
console.log("Wrote", dest, "(", (out.length / 1024).toFixed(0), "KB )");
